#include <bits/stdc++.h>
using namespace std;

#define INF (int)1e+9

int main() {
	int t,n,k;
	string s;

	cin>>t;
	for(int itest=0;itest<t;itest++){
		cin>>s;
		cin>>k;
		n=s.size();

		vector<int>x(n+1),y(n+1),z(n+1);
		vector<vector<int> >dp(n+1,vector<int>(k+1));

		for(int i=3;i<=n;i++){
			if(s[i-3]!='A')y[i]++;
			if(s[i-2]!='B')y[i]++;
			if(s[i-1]!='C')y[i]++;
			if(y[i]==0)z[i]++;
			for(int j=0;j<3;j++){
				if(i+j<=n)x[i+j]+=z[i];
			}
		}

		for(int j=1;j<=k;j++)dp[0][j]=INF;
		for(int i=1;i<=n;i++){
			for(int j=1;j<=k;j++){
				dp[i][j]=INF;
				if(j+z[i]<=k)dp[i][j]=min(dp[i][j],dp[i-1][j+z[i]]);
				if(i>=3)dp[i][j]=min(dp[i][j],dp[i-3][j-1+x[i]]+y[i]);
			}
		}
		if(dp[n][k]>=INF)cout<<-1<<endl;
		else cout<<dp[n][k]<<endl;
	}
	return 0;
}
